//! DLP API Hook DLL — cloud sync client interception (T03).
//!
//! This DLL is injected into sync client processes (OneDrive, Dropbox, etc.)
//! to intercept file creation at `CreateFileW` and `NtCreateFile`.  In this
//! skeleton phase the exports are no-op trampolines that delegate to the
//! original functions; the actual IAT patching and classification logic will
//! be added in a future slice.
//!
//! ## Exports
//!
//! | Symbol | Purpose |
//! |--------|---------|
//! | `HookCreateFileW` | Trampoline for `CreateFileW` |
//! | `HookNtCreateFile` | Trampoline for `NtCreateFile` |
//! | `UnhookAll` | Restores original function pointers |

use std::sync::atomic::{AtomicBool, Ordering};
use windows::core::{w, PCWSTR};
use windows::Win32::Foundation::{HANDLE, NTSTATUS};
use windows::Win32::Storage::FileSystem::{
    FILE_CREATION_DISPOSITION, FILE_FLAGS_AND_ATTRIBUTES, FILE_SHARE_MODE,
};
use windows::Win32::Security::SECURITY_ATTRIBUTES;
use windows::Win32::System::Diagnostics::Debug::OutputDebugStringW;

/// Guard to ensure one-time initialisation.
static INITIALISED: AtomicBool = AtomicBool::new(false);

/// Original `CreateFileW` pointer saved before patching.
///
/// SAFETY: written once during `DllMain` / init, then read-only.
static mut ORIGINAL_CREATE_FILE_W: Option<unsafe extern "system" fn()> = None;

/// Original `NtCreateFile` pointer saved before patching.
///
/// SAFETY: written once during `DllMain` / init, then read-only.
static mut ORIGINAL_NT_CREATE_FILE: Option<
    unsafe extern "system" fn(
        *mut HANDLE,
        u32,
        *mut std::ffi::c_void, // OBJECT_ATTRIBUTES*
        *mut std::ffi::c_void, // IO_STATUS_BLOCK*
        *const i64,            // LARGE_INTEGER*
        u32,
        u32,
        u32,
        u32,
        *mut std::ffi::c_void, // EaBuffer*
        u32,
    ) -> NTSTATUS,
> = None;

/// Logs a wide-string message via `OutputDebugStringW`.
fn debug_log(msg: &str) {
    let wide: Vec<u16> = msg.encode_utf16().chain(std::iter::once(0)).collect();
    unsafe { OutputDebugStringW(PCWSTR::from_raw(wide.as_ptr())) };
}

/// Resolves a function from `kernel32.dll` by name.
unsafe fn resolve_kernel32_proc(name: windows::core::PCSTR) -> Option<unsafe extern "system" fn()> {
    use windows::Win32::System::LibraryLoader::{GetModuleHandleW, GetProcAddress};
    let kernel32 = GetModuleHandleW(w!("kernel32.dll")).ok()?;
    let proc = GetProcAddress(kernel32, name)?;
    Some(std::mem::transmute(proc))
}

/// Initialises the hook DLL.
///
/// Saves original function pointers so trampolines and `UnhookAll` work.
/// Called automatically from `DllMain` on process attach.
fn init() {
    if INITIALISED.swap(true, Ordering::SeqCst) {
        return;
    }

    unsafe {
        ORIGINAL_CREATE_FILE_W =
            resolve_kernel32_proc(windows::core::s!("CreateFileW"));
        ORIGINAL_NT_CREATE_FILE = resolve_nt_create_file();
    }

    debug_log("[dlp-hook] initialised — no-op trampolines active\0");
}

/// Resolves `NtCreateFile` from `ntdll.dll`.
unsafe fn resolve_nt_create_file() -> Option<
    unsafe extern "system" fn(
        *mut HANDLE,
        u32,
        *mut std::ffi::c_void,
        *mut std::ffi::c_void,
        *const i64,
        u32,
        u32,
        u32,
        u32,
        *mut std::ffi::c_void,
        u32,
    ) -> NTSTATUS,
> {
    use windows::Win32::System::LibraryLoader::{GetModuleHandleW, GetProcAddress};

    let ntdll = GetModuleHandleW(w!("ntdll.dll")).ok()?;
    let proc = GetProcAddress(ntdll, windows::core::s!("NtCreateFile"))?;
    Some(std::mem::transmute(proc))
}

/// DLL entry point.
#[unsafe(no_mangle)]
extern "system" fn DllMain(_inst: isize, reason: u32, _reserved: usize) -> i32 {
    const DLL_PROCESS_ATTACH: u32 = 1;
    if reason == DLL_PROCESS_ATTACH {
        init();
    }
    1
}

// ─────────────────────────────────────────────────────────────────────────────
// Exported trampolines
// ─────────────────────────────────────────────────────────────────────────────

/// Trampoline for `CreateFileW`.
///
/// In the skeleton phase this simply calls the original function.
/// Future slices will add classification before/after the call.
#[unsafe(no_mangle)]
pub unsafe extern "system" fn HookCreateFileW(
    lpfilename: PCWSTR,
    dwdesiredaccess: u32,
    dwsharemode: FILE_SHARE_MODE,
    lpsecurityattributes: *const SECURITY_ATTRIBUTES,
    dwcreationdisposition: FILE_CREATION_DISPOSITION,
    dwflagsandattributes: FILE_FLAGS_AND_ATTRIBUTES,
    htemplatefile: HANDLE,
) -> HANDLE {
    let original = ORIGINAL_CREATE_FILE_W.unwrap_or_else(|| {
        resolve_kernel32_proc(windows::core::s!("CreateFileW"))
            .unwrap_or(std::mem::transmute(std::ptr::null::<()>()))
    });
    let original_fn: unsafe extern "system" fn(
        PCWSTR,
        u32,
        FILE_SHARE_MODE,
        *const SECURITY_ATTRIBUTES,
        FILE_CREATION_DISPOSITION,
        FILE_FLAGS_AND_ATTRIBUTES,
        HANDLE,
    ) -> HANDLE = std::mem::transmute(original);
    original_fn(
        lpfilename,
        dwdesiredaccess,
        dwsharemode,
        lpsecurityattributes,
        dwcreationdisposition,
        dwflagsandattributes,
        htemplatefile,
    )
}

/// Trampoline for `NtCreateFile`.
///
/// In the skeleton phase this simply calls the original function.
#[unsafe(no_mangle)]
pub unsafe extern "system" fn HookNtCreateFile(
    filehandle: *mut HANDLE,
    desiredaccess: u32,
    objectattributes: *mut std::ffi::c_void,
    iostatusblock: *mut std::ffi::c_void,
    allocationsize: *const i64,
    fileattributes: u32,
    shareaccess: u32,
    createdisposition: u32,
    createoptions: u32,
    eabuffer: *mut std::ffi::c_void,
    ealength: u32,
) -> NTSTATUS {
    let original = ORIGINAL_NT_CREATE_FILE.unwrap_or_else(|| {
        // Fallback: resolve dynamically if init failed.
        resolve_nt_create_file().unwrap_or(std::mem::transmute(std::ptr::null::<()>()))
    });
    original(
        filehandle,
        desiredaccess,
        objectattributes,
        iostatusblock,
        allocationsize,
        fileattributes,
        shareaccess,
        createdisposition,
        createoptions,
        eabuffer,
        ealength,
    )
}

/// Restores original function pointers.
///
/// Called by the agent before unloading the DLL from a target process.
#[unsafe(no_mangle)]
pub extern "system" fn UnhookAll() {
    debug_log("[dlp-hook] UnhookAll called — restoring originals\0");
    // In the skeleton phase there is nothing to restore because we never
    // patched the IAT.  Future slices will walk the IAT and restore saved
    // pointers here.
}

//! Hook IPC — named-pipe protocol between API-hook DLL and agent service.
//!
//! Each frame on the pipe is encoded as:
//! ```text
//! [u32: payload_length_le] [bincode payload]
//! ```
//!
//! The server runs a blocking accept loop (intended to be spawned on a
//! dedicated `std::thread`).  When a Tokio runtime is available on the
//! calling thread, each connection is handled in a
//! `tokio::task::spawn_blocking` task so the accept loop never blocks on
//! classification work.

use std::sync::Arc;

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use tracing::{debug, info, warn};
use windows::core::PCWSTR;
use windows::Win32::Foundation::{CloseHandle, HANDLE};
use windows::Win32::Storage::FileSystem::{
    CreateFileW, FILE_GENERIC_READ, FILE_GENERIC_WRITE, FILE_SHARE_NONE,
    OPEN_EXISTING, PIPE_ACCESS_DUPLEX,
};
use windows::Win32::System::Pipes::{
    ConnectNamedPipe, CreateNamedPipeW, DisconnectNamedPipe, NAMED_PIPE_MODE,
    PIPE_READMODE_MESSAGE, PIPE_TYPE_MESSAGE, PIPE_WAIT,
};

use dlp_common::Decision;

use crate::ipc::frame::{read_frame, write_frame};
use crate::ipc::pipe_security::PipeSecurity;

/// Default pipe name used by the hook DLL.
pub const DEFAULT_PIPE_NAME: &str = r"\\.\pipe\DlpHookPipe";

/// Number of pipe instances to allow.
const NUM_INSTANCES: u32 = 4;

/// Output / input buffer size.
const PIPE_BUFFER_SIZE: u32 = 65_536;

/// Default timeout for `CreateNamedPipeW`.
const PIPE_TIMEOUT_MS: u32 = 5_000;

/// Request sent by the hook DLL to the agent for classification.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct HookRequest {
    pub path: String,
    pub action: String,
}

/// Response returned by the agent to the hook DLL.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct HookResponse {
    pub decision: Decision,
    pub reason: String,
}

/// Handler type for processing hook requests.
pub type HookHandler = Arc<dyn Fn(HookRequest) -> HookResponse + Send + Sync + 'static>;

/// Named-pipe server that listens for hook DLL classification requests.
pub struct HookIpcServer {
    pipe_name: String,
    handler: HookHandler,
}

impl HookIpcServer {
    /// Creates a new hook IPC server.
    ///
    /// `pipe_name` is the full Win32 pipe path (e.g. `r"\\.\pipe\DlpHookPipe"`).
    /// `handler` is called once per request to produce a [`HookResponse`].
    pub fn new(pipe_name: impl Into<String>, handler: HookHandler) -> Self {
        Self {
            pipe_name: pipe_name.into(),
            handler,
        }
    }

    /// Runs the blocking accept loop on the current thread.
    ///
    /// Callers should spawn this in a dedicated `std::thread`.  If a Tokio
    /// runtime is present on the calling thread, each accepted connection is
    /// off-loaded to `tokio::task::spawn_blocking` so the accept loop stays
    /// responsive.
    pub fn run(self) -> Result<()> {
        self.run_with_ready(|| {})
    }

    /// Same as [`run`](Self::run) but calls `on_ready` after the first pipe
    /// instance has been created and is ready for clients.
    pub fn run_with_ready(self, on_ready: impl FnOnce()) -> Result<()> {
        info!(pipe = %self.pipe_name, "Hook IPC server starting");
        let rt = tokio::runtime::Handle::try_current().ok();
        let pipe = create_pipe(&self.pipe_name)?;
        on_ready();
        accept_loop(pipe, self.pipe_name, self.handler, rt)
    }
}

fn pipe_mode() -> NAMED_PIPE_MODE {
    PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT
}

fn create_pipe(pipe_name: &str) -> Result<HANDLE> {
    let name_wide: Vec<u16> = pipe_name.encode_utf16().chain(std::iter::once(0)).collect();
    let sec = PipeSecurity::new().context("pipe security descriptor")?;

    let pipe = unsafe {
        CreateNamedPipeW(
            PCWSTR::from_raw(name_wide.as_ptr()),
            PIPE_ACCESS_DUPLEX,
            pipe_mode(),
            NUM_INSTANCES,
            PIPE_BUFFER_SIZE,
            PIPE_BUFFER_SIZE,
            PIPE_TIMEOUT_MS,
            Some(sec.as_ptr()),
        )
    };

    if pipe.is_invalid() {
        return Err(anyhow::anyhow!(
            "CreateNamedPipeW returned INVALID_HANDLE_VALUE"
        ));
    }
    Ok(pipe)
}

fn accept_loop(
    first_pipe: HANDLE,
    pipe_name: String,
    handler: HookHandler,
    rt: Option<tokio::runtime::Handle>,
) -> Result<()> {
    let mut pipe = first_pipe;
    loop {
        // Wait for a client. ERROR_PIPE_CONNECTED (535) means a client
        // already connected between CreateNamedPipeW and ConnectNamedPipe.
        if let Err(e) = unsafe { ConnectNamedPipe(pipe, None) } {
            let win32_code = (e.code().0 as u32) & 0xFFFF;
            if win32_code != 535 {
                warn!(win32_code, "Hook IPC: ConnectNamedPipe failed — recycling pipe");
                let _ = unsafe { CloseHandle(pipe) };
                pipe = create_pipe(&pipe_name)?;
                continue;
            }
            debug!("Hook IPC: client already connected (535)");
        }

        info!("Hook IPC: client connected");

        match rt {
            Some(ref _h) => {
                // Synchronous handling (same as no-runtime path).  In a
                // future integration the handler may internally spawn Tokio
                // tasks for async classification; the accept loop itself
                // stays synchronous because Win32 pipe APIs are blocking.
                if let Err(e) = handle_connection(pipe, &handler) {
                    warn!(error = %e, "Hook IPC: connection handler error");
                }
                let _ = unsafe { DisconnectNamedPipe(pipe) };
                let _ = unsafe { CloseHandle(pipe) };
            }
            None => {
                if let Err(e) = handle_connection(pipe, &handler) {
                    warn!(error = %e, "Hook IPC: connection handler error");
                }
                let _ = unsafe { DisconnectNamedPipe(pipe) };
                let _ = unsafe { CloseHandle(pipe) };
            }
        }

        pipe = create_pipe(&pipe_name)?;
    }
}

fn handle_connection(pipe: HANDLE, handler: &HookHandler) -> Result<()> {
    loop {
        let frame = match read_frame(pipe) {
            Ok(f) => f,
            Err(e) => {
                debug!(error = %e, "Hook IPC: read error — disconnecting");
                break;
            }
        };

        let request: HookRequest = match bincode::deserialize(&frame) {
            Ok(r) => r,
            Err(e) => {
                warn!(error = %e, "Hook IPC: malformed request — bincode deserialization failed");
                continue;
            }
        };

        debug!(path = %request.path, action = %request.action, "Hook IPC: classifying");
        let response = handler(request);
        debug!(decision = ?response.decision, "Hook IPC: classification complete");

        let payload = bincode::serialize(&response).context("serialize response")?;
        if let Err(e) = write_frame(pipe, &payload) {
            warn!(error = %e, "Hook IPC: write response failed — disconnecting");
            break;
        }
    }

    Ok(())
}

// ─────────────────────────────────────────────────────────────────────────────
// Client helpers (used by tests and, in the future, the hook DLL)
// ─────────────────────────────────────────────────────────────────────────────

/// Connects to a named pipe as a client.
///
/// Returns `Err` if the pipe does not exist or the server is not listening.
pub fn connect_client(pipe_name: &str) -> Result<HANDLE> {
    let name_wide: Vec<u16> = pipe_name.encode_utf16().chain(std::iter::once(0)).collect();

    let handle = unsafe {
        CreateFileW(
            PCWSTR::from_raw(name_wide.as_ptr()),
            FILE_GENERIC_READ.0 | FILE_GENERIC_WRITE.0,
            FILE_SHARE_NONE,
            None,
            OPEN_EXISTING,
            windows::Win32::Storage::FileSystem::FILE_FLAGS_AND_ATTRIBUTES(0),
            None,
        )
    };

    match handle {
        Ok(h) => Ok(h),
        Err(e) => {
            let code = (e.code().0 as u32) & 0xFFFF;
            Err(anyhow::anyhow!(
                "CreateFileW failed (win32={}) — pipe server not running?",
                code
            ))
        }
    }
}

/// Sends a [`HookRequest`] over an open pipe and returns the [`HookResponse`].
pub fn send_request(pipe: HANDLE, request: &HookRequest) -> Result<HookResponse> {
    let payload = bincode::serialize(request).context("serialize request")?;
    write_frame(pipe, &payload).context("write request frame")?;

    let frame = read_frame(pipe).context("read response frame")?;
    let response: HookResponse = bincode::deserialize(&frame).context("deserialize response")?;
    Ok(response)
}

/// Sends raw bytes over an open pipe and reads the response frame.
pub fn send_raw(pipe: HANDLE, raw: &[u8]) -> Result<Vec<u8>> {
    write_frame(pipe, raw).context("write raw frame")?;
    let frame = read_frame(pipe).context("read response frame")?;
    Ok(frame)
}

/// Closes a pipe handle.
pub fn close_pipe(pipe: HANDLE) {
    let _ = unsafe { CloseHandle(pipe) };
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use std::time::{Duration, Instant};

    use super::*;

    /// Starts a [`HookIpcServer`] on a dedicated thread using the given
    /// handler, waits until the pipe is created, and returns the thread
    /// handle so the caller can join it later.
    fn start_server(
        pipe_name: &str,
        handler: HookHandler,
    ) -> std::thread::JoinHandle<Result<()>> {
        let name = pipe_name.to_string();
        let (tx, rx) = std::sync::mpsc::channel::<()>();
        let handle = std::thread::spawn(move || {
            let server = HookIpcServer::new(name, handler);
            server.run_with_ready(|| {
                let _ = tx.send(());
            })
        });

        rx.recv_timeout(Duration::from_secs(5))
            .expect("server did not become ready within 5s");
        handle
    }

    #[test]
    fn hook_ipc_roundtrip_test() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestRoundtrip";

        let handler: HookHandler = Arc::new(|req: HookRequest| HookResponse {
            decision: Decision::DENY,
            reason: format!("blocked: {}", req.path),
        });

        let _server_handle = start_server(pipe_name, handler);

        // Give the server thread time to enter ConnectNamedPipe before the
        // client connects.  Without this, CreateFileW may race ahead and the
        // server's subsequent ConnectNamedPipe + handle_connection can see a
        // broken pipe before the client writes.
        std::thread::sleep(Duration::from_millis(50));

        let client = connect_client(pipe_name).expect("client connect");

        let mut latencies: Vec<Duration> = Vec::with_capacity(1_000);

        for i in 0..1_000 {
            let req = HookRequest {
                path: format!(r"C:\Users\test\file{}.txt", i),
                action: "CREATE".to_string(),
            };

            let start = Instant::now();
            let resp = send_request(client, &req).expect("request/response");
            let elapsed = start.elapsed();

            assert_eq!(resp.decision, Decision::DENY);
            assert_eq!(resp.reason, format!("blocked: {}", req.path));
            latencies.push(elapsed);

        }

        close_pipe(client);

        // Drop the server by … nothing; we just let the thread run out.
        // In a real scenario we'd send a shutdown signal.  For the test we
        // simply abandon the pipe — the server thread will block on the
        // next ConnectNamedPipe.  That's acceptable for unit tests.

        latencies.sort();
        let p99_idx = (latencies.len() as f64 * 0.99).ceil() as usize - 1;
        let p99 = latencies[p99_idx.min(latencies.len() - 1)];

        println!("p99 latency: {:?}", p99);
        println!("median latency: {:?}", latencies[latencies.len() / 2]);
        println!("min latency: {:?}", latencies[0]);
        println!("max latency: {:?}", latencies[latencies.len() - 1]);

        assert!(
            p99 < Duration::from_millis(50),
            "p99 latency {}ms >= 50ms",
            p99.as_millis()
        );

        // Clean up: we can't gracefully stop the server, but we can at
        // least join the thread with a timeout so it doesn't leak forever
        // in test runners.
        // Server thread blocks in ConnectNamedPipe — do not join.
    }

    #[test]
    fn hook_ipc_empty_path_boundary() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestEmpty";

        let handler: HookHandler = Arc::new(|req: HookRequest| HookResponse {
            decision: Decision::ALLOW,
            reason: if req.path.is_empty() {
                "empty path ok".to_string()
            } else {
                "non-empty".to_string()
            },
        });

        let _server_handle = start_server(pipe_name, handler);
        let client = connect_client(pipe_name).expect("client connect");

        let req = HookRequest {
            path: "".to_string(),
            action: "READ".to_string(),
        };
        let resp = send_request(client, &req).expect("send empty path request");
        assert_eq!(resp.decision, Decision::ALLOW);
        assert_eq!(resp.reason, "empty path ok");

        close_pipe(client);
        // Server thread blocks in ConnectNamedPipe — do not join.
    }

    #[test]
    fn hook_ipc_zero_byte_payload_returns_no_response() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestZero";

        let handler: HookHandler = Arc::new(|_req: HookRequest| HookResponse {
            decision: Decision::DENY,
            reason: "never reached".to_string(),
        });

        let _server_handle = start_server(pipe_name, handler);
        let client = connect_client(pipe_name).expect("client connect");

        // Write a zero-byte payload (length = 0, no payload bytes).
        let zero_len = 0u32.to_le_bytes();
        let written = unsafe {
            let mut bytes_written = 0u32;
            windows::Win32::Storage::FileSystem::WriteFile(
                client,
                Some(&zero_len),
                Some(&mut bytes_written),
                None,
            )
            .is_ok()
        };
        assert!(written);

        // Close our end so the server detects the disconnect and leaves
        // handle_connection.  Then ReadFile on our (now-invalid) handle
        // should fail.
        close_pipe(client);

        // The server will try to bincode::deserialize an empty slice and
        // log a warning, then close the connection without writing a
        // response.  ReadFile should therefore fail or return 0.
        let mut buf = [0u8; 4];
        let result = unsafe {
            let mut read = 0u32;
            windows::Win32::Storage::FileSystem::ReadFile(
                client,
                Some(&mut buf),
                Some(&mut read),
                None,
            )
        };

        // Either ReadFile errors or the pipe closes (0 bytes read).
        assert!(
            result.is_err() || {
                let mut read = 0u32;
                unsafe {
                    windows::Win32::Storage::FileSystem::ReadFile(
                        client,
                        Some(&mut buf),
                        Some(&mut read),
                        None,
                    )
                    .ok();
                }
                read == 0
            },
            "expected broken pipe after zero-byte payload"
        );

        // Server thread blocks in ConnectNamedPipe — do not join.
    }

    #[test]
    fn hook_ipc_malformed_request_logged_and_dropped() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestMalformed";

        let handler: HookHandler = Arc::new(|_req: HookRequest| HookResponse {
            decision: Decision::DENY,
            reason: "should not reach".to_string(),
        });

        let _server_handle = start_server(pipe_name, handler);
        let client = connect_client(pipe_name).expect("client connect");

        // Send a valid-length frame but with garbage bytes that are not
        // valid bincode for HookRequest.
        let garbage = b"\x01\x02\x03\x04\x05\x06\x07\x08";
        let frame_len = (garbage.len() as u32).to_le_bytes();
        let mut payload = Vec::with_capacity(4 + garbage.len());
        payload.extend_from_slice(&frame_len);
        payload.extend_from_slice(garbage);

        let written = unsafe {
            let mut bytes_written = 0u32;
            windows::Win32::Storage::FileSystem::WriteFile(
                client,
                Some(&payload),
                Some(&mut bytes_written),
                None,
            )
            .is_ok()
        };
        assert!(written);

        // Because the server deserialisation fails, it drops the
        // connection without a response.  The next read should fail.
        let mut buf = [0u8; 4];
        let result = unsafe {
            let mut read = 0u32;
            windows::Win32::Storage::FileSystem::ReadFile(
                client,
                Some(&mut buf),
                Some(&mut read),
                None,
            )
        };
        assert!(
            result.is_err() || {
                let mut read = 0u32;
                unsafe {
                    windows::Win32::Storage::FileSystem::ReadFile(
                        client,
                        Some(&mut buf),
                        Some(&mut read),
                        None,
                    )
                    .ok();
                }
                read == 0
            },
            "expected broken pipe after malformed request"
        );

        close_pipe(client);
        // Server thread blocks in ConnectNamedPipe — do not join.
    }

    #[test]
    fn hook_ipc_server_not_running_connect_fails() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestNoServer";
        let result = connect_client(pipe_name);
        assert!(result.is_err(), "expected connection to fail when server is not running");
    }

    #[test]
    fn hook_ipc_oversized_path_frame_rejected() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestOversized";

        let handler: HookHandler = Arc::new(|_req: HookRequest| HookResponse {
            decision: Decision::DENY,
            reason: "ok".to_string(),
        });

        let _server_handle = start_server(pipe_name, handler);
        let client = connect_client(pipe_name).expect("client connect");

        // Build a path well over 32KB.
        let huge_path = "A".repeat(40_000);
        let req = HookRequest {
            path: huge_path,
            action: "WRITE".to_string(),
        };

        // Serialisation itself should succeed.
        let _payload = bincode::serialize(&req).expect("serialize oversized path");
        // The frame is ~40KB, which is under the 64MiB limit in frame.rs,
        // so it should go through.  We verify the server handles it.
        let resp = send_request(client, &req).expect("request/response with oversized path");
        assert_eq!(resp.decision, Decision::DENY);

        close_pipe(client);
        // Server thread blocks in ConnectNamedPipe — do not join.
    }
}

//! ABAC types — Subject, Resource, Environment, Action, and Policy.
//!
//! These types define the attribute model used by the Policy Engine's
//! Attribute-Based Access Control evaluation layer.

use crate::endpoint::AppIdentity;
use serde::{Deserialize, Serialize};

/// The action the user is attempting to perform on a resource.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[allow(non_camel_case_types)]
pub enum Action {
    /// Read a file.
    #[default]
    READ,
    /// Write or modify a file.
    WRITE,
    /// Copy a file (e.g., to USB or network share).
    COPY,
    /// Delete a file.
    DELETE,
    /// Move a file (rename or relocate).
    MOVE,
    /// Paste from clipboard (copying text/data into an application).
    PASTE,
    /// Admin created a new policy via the admin API.
    PolicyCreate,
    /// Admin updated an existing policy via the admin API.
    PolicyUpdate,
    /// Admin deleted a policy via the admin API.
    PolicyDelete,
    /// Admin changed own password via the admin API.
    PasswordChange,
    /// Admin added a disk to the server-side disk allowlist (Phase 37, AUDIT-03).
    DiskRegistryAdd,
    /// Admin removed a disk from the server-side disk allowlist (Phase 37, AUDIT-03).
    DiskRegistryRemove,
    /// Drag-and-drop operation (Phase 40, APP-08).
    DRAG_DROP,
    /// Cloud upload operation (Phase 45, M017/S01).
    CLOUD_UPLOAD,
}

/// The access context describes how the file operation originated.
///
/// `local` — the file operation originates from a process running locally.
/// `smb` — the file operation originates from a remote client over SMB.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum AccessContext {
    /// Operation originates from the local process.
    #[default]
    Local,
    /// Operation originates from a remote SMB client.
    Smb,
}

/// The system action the ABAC engine returns after evaluation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum Decision {
    /// Permit the operation without additional logging.
    #[default]
    ALLOW,
    /// Block the operation and log the event.
    DENY,
    /// Permit the operation but emit an audit event.
    #[serde(rename = "ALLOW_WITH_LOG")]
    AllowWithLog,
    /// Block the operation, log the event, and trigger an immediate SIEM/admin alert.
    #[serde(rename = "DENY_WITH_ALERT")]
    DenyWithAlert,
}

impl Decision {
    /// Returns `true` if this decision blocks the operation.
    #[must_use]
    pub fn is_denied(self) -> bool {
        matches!(self, Self::DENY | Self::DenyWithAlert)
    }

    /// Returns `true` if this decision should trigger an alert.
    #[must_use]
    pub fn is_alert(self) -> bool {
        matches!(self, Self::DenyWithAlert)
    }

    /// Returns `true` if this decision requires an audit event to be emitted.
    #[must_use]
    pub fn requires_audit(self) -> bool {
        matches!(self, Self::DENY | Self::DenyWithAlert | Self::AllowWithLog)
    }
}

/// The trust level of the device the user is operating from.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "PascalCase")]
pub enum DeviceTrust {
    /// Device is managed by the organization (e.g., domain-joined, MDM-enrolled).
    Managed,
    /// Device is not managed by the organization.
    #[default]
    Unmanaged,
    /// Device meets the organization's compliance requirements.
    Compliant,
    /// Device trust level is unknown or indeterminate.
    Unknown,
}

/// Network location inferred from the client's IP address or VPN status.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "PascalCase")]
pub enum NetworkLocation {
    /// Device is on the corporate network (wired or wireless).
    Corporate,
    /// Device is connected via VPN.
    CorporateVpn,
    /// Device is on a guest or untrusted network.
    Guest,
    /// Location is unknown or could not be determined.
    #[default]
    Unknown,
}

/// The requesting user and their attributes.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Subject {
    /// The user's Windows Security Identifier (e.g., "S-1-5-21-...").
    pub user_sid: String,
    /// The user's display name (e.g., "jsmith").
    pub user_name: String,
    /// The Windows Security Identifiers of all AD groups the user is a member of.
    pub groups: Vec<String>,
    /// The trust level of the device the user is operating from.
    #[serde(default)]
    pub device_trust: DeviceTrust,
    /// The network location of the device.
    #[serde(default)]
    pub network_location: NetworkLocation,
}

/// The file resource being accessed.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Resource {
    /// The full path to the file or directory (e.g., "C:\\Data\\Q4-Financials.xlsx").
    pub path: String,
    /// The classification tier of the resource.
    pub classification: crate::Classification,
}

/// The environmental context at the time of the access request.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(default)]
pub struct Environment {
    /// The current time on the endpoint.
    pub timestamp: chrono::DateTime<chrono::Utc>,
    /// The session ID of the interactive session making the request.
    pub session_id: u32,
    /// Whether the request is originating from a remote SMB context.
    #[serde(default)]
    pub access_context: AccessContext,
}

/// Identity information about the requesting agent endpoint.
///
/// This is logged by the Policy Engine on every evaluation request to
/// identify which machine and user is making the request.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct AgentInfo {
    /// Machine hostname, e.g. "WORKSTATION-01".
    pub machine_name: Option<String>,
    /// The Windows username of the interactive session that triggered the request,
    /// e.g. "jsmith".
    pub current_user: Option<String>,
}

/// A complete ABAC evaluation request.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct EvaluateRequest {
    pub subject: Subject,
    pub resource: Resource,
    pub environment: Environment,
    pub action: Action,
    /// Agent endpoint identity — machine name and interactive user.
    /// Logged by the Policy Engine for request tracing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub agent: Option<AgentInfo>,
    /// Resolved identity of the application that initiated the request
    /// (e.g. the process that copied clipboard content). Populated by
    /// Phase 25. `None` on requests from agents that predate Phase 25.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_application: Option<AppIdentity>,
    /// Resolved identity of the destination application (e.g. the
    /// paste target). Populated by Phase 25.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_application: Option<AppIdentity>,
    /// Source origin URL for browser clipboard events (e.g., the page where paste occurs).
    /// Populated by Phase 41 Chrome handler. `None` on requests from agents that predate Phase 41.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_origin: Option<String>,
    /// Destination origin URL for browser clipboard events.
    /// Chrome Content Analysis API v1 does not expose this; always `None` in v0.8.0.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_origin: Option<String>,
}

/// Internal ABAC evaluation context.
///
/// Constructed from [`EvaluateRequest`] at the evaluate boundary in Phase 26.
/// Mirrors [`EvaluateRequest`] fields minus wire-only metadata: there is
/// deliberately no `agent` field (per Phase 22 D-10) because `AgentInfo`
/// is request-tracing metadata, not an ABAC attribute.
///
/// Defined in Phase 22 so downstream crates compile against the type
/// before Phase 26 wires it into [`crate::abac::EvaluateRequest`]-to-context
/// conversion at `PolicyStore::evaluate()`.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct AbacContext {
    pub subject: Subject,
    pub resource: Resource,
    pub environment: Environment,
    pub action: Action,
    /// Resolved identity of the application that initiated the operation.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_application: Option<AppIdentity>,
    /// Resolved identity of the destination application (paste target).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_application: Option<AppIdentity>,
    /// Source origin URL for browser clipboard events.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub source_origin: Option<String>,
    /// Destination origin URL for browser clipboard events.
    /// Chrome Content Analysis API v1 does not expose this; always `None` in v0.8.0.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub destination_origin: Option<String>,
}

/// A complete ABAC evaluation response.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EvaluateResponse {
    /// The enforcement decision.
    pub decision: Decision,
    /// The ID of the policy that matched (if any).
    pub matched_policy_id: Option<String>,
    /// A human-readable reason string for the decision.
    pub reason: String,
}

impl EvaluateResponse {
    /// Constructs a default-deny response for when no policy matches.
    pub fn default_deny() -> Self {
        Self {
            decision: Decision::DENY,
            matched_policy_id: None,
            reason: "No matching policy; default deny".to_string(),
        }
    }

    /// Constructs a permit response for when no policy matches and the system is
    /// configured for default-allow on non-sensitive resources.
    #[must_use]
    pub fn default_allow() -> Self {
        Self {
            decision: Decision::ALLOW,
            matched_policy_id: None,
            reason: "No matching policy; default allow".to_string(),
        }
    }
}

/// The application-identity field targeted by a [`PolicyCondition`].
///
/// Used with `SourceApplication` and `DestinationApplication` condition variants
/// to select which field of [`crate::endpoint::AppIdentity`] to compare.
///
/// # Serde
///
/// Serializes as snake_case: `"publisher"`, `"image_path"`, `"trust_tier"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AppField {
    /// Publisher common name from the Authenticode certificate (e.g., `"Microsoft Corporation"`).
    Publisher,
    /// Full NT image path of the process (e.g., `C:\Program Files\App\app.exe`).
    ImagePath,
    /// Application trust tier assigned by the Phase 25 publisher-verification pipeline.
    TrustTier,
    /// Application User Model ID (AUMID) for UWP apps (Phase 39).
    Aumid,
    /// Package Family Name for UWP apps (Phase 39).
    PackageFamilyName,
}

impl From<EvaluateRequest> for AbacContext {
    /// Converts a wire [`EvaluateRequest`] into an internal [`AbacContext`].
    ///
    /// The `agent` field is intentionally dropped — `AgentInfo` is
    /// request-tracing metadata, not an ABAC attribute (Phase 22 D-10).
    ///
    /// # Arguments
    ///
    /// * `req` - The wire-format evaluation request to convert.
    ///
    /// # Returns
    ///
    /// An [`AbacContext`] with `subject`, `resource`, `environment`, `action`,
    /// `source_application`, `destination_application`, `source_origin`, and
    /// `destination_origin` forwarded from `req`.
    fn from(req: EvaluateRequest) -> Self {
        Self {
            subject: req.subject,
            resource: req.resource,
            environment: req.environment,
            action: req.action,
            source_application: req.source_application,
            destination_application: req.destination_application,
            source_origin: req.source_origin,
            destination_origin: req.destination_origin,
        }
    }
}

/// A condition within an ABAC policy rule.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "attribute", rename_all = "snake_case")]
pub enum PolicyCondition {
    /// Match by resource classification tier.
    Classification {
        #[serde(rename = "op")]
        op: String,
        value: crate::Classification,
    },
    /// Match by AD group membership.
    MemberOf {
        #[serde(rename = "op")]
        op: String,
        group_sid: String,
    },
    /// Match by device trust level.
    DeviceTrust {
        #[serde(rename = "op")]
        op: String,
        value: DeviceTrust,
    },
    /// Match by network location.
    NetworkLocation {
        #[serde(rename = "op")]
        op: String,
        value: NetworkLocation,
    },
    /// Match by access context (local vs. SMB).
    AccessContext {
        #[serde(rename = "op")]
        op: String,
        value: AccessContext,
    },
    /// Match by the source application's identity (the process that initiated the operation).
    ///
    /// If `source_application` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no identity means the condition cannot be confirmed, per D-03).
    SourceApplication {
        /// Which field of [`crate::endpoint::AppIdentity`] to compare.
        field: AppField,
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"` (ImagePath only).
        #[serde(rename = "op")]
        op: String,
        /// The value to compare against (string form).
        value: String,
    },
    /// Match by the destination application's identity (the paste target process).
    ///
    /// If `destination_application` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no identity means the condition cannot be confirmed, per D-03).
    DestinationApplication {
        /// Which field of [`crate::endpoint::AppIdentity`] to compare.
        field: AppField,
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"` (ImagePath only).
        #[serde(rename = "op")]
        op: String,
        /// The value to compare against (string form).
        value: String,
    },
    /// Match by the source origin URL (the page where the clipboard paste is occurring).
    ///
    /// If `source_origin` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no origin means the condition cannot be confirmed, per D-03).
    SourceOrigin {
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"`.
        #[serde(rename = "op")]
        op: String,
        /// The origin string to compare against (e.g., `"https://sharepoint.com"`).
        value: String,
    },
    /// Match by the destination origin URL (the page where content is being pasted).
    ///
    /// If `destination_origin` is `None` on the [`AbacContext`], this condition does NOT match
    /// (fails closed — no origin means the condition cannot be confirmed, per D-03).
    DestinationOrigin {
        /// Comparison operator: `"eq"`, `"ne"`, or `"contains"`.
        #[serde(rename = "op")]
        op: String,
        /// The origin string to compare against (e.g., `"https://example.com"`).
        value: String,
    },
}

/// The boolean composition mode for a policy's condition list.
///
/// - `ALL`: every condition must match (implicit v0.4.0 behavior).
/// - `ANY`: at least one condition must match.
/// - `NONE`: no condition may match.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
pub enum PolicyMode {
    /// Every condition must match.
    #[default]
    ALL,
    /// At least one condition must match.
    ANY,
    /// No condition may match.
    NONE,
}

/// An ABAC policy rule.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct Policy {
    /// Unique identifier for this policy version.
    pub id: String,
    /// Human-readable name.
    pub name: String,
    /// Optional description.
    pub description: Option<String>,
    /// Relative priority — lower numbers are evaluated first; first-match wins.
    pub priority: u32,
    /// The conditions that must all be satisfied for this policy to match.
    pub conditions: Vec<PolicyCondition>,
    /// The system action to apply when this policy matches.
    pub action: Decision,
    /// Whether this policy is currently active.
    pub enabled: bool,
    /// Boolean composition mode for the conditions list.
    #[serde(default)]
    pub mode: PolicyMode,
    /// Monotonically increasing version number.
    pub version: u64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_abac_context_default() {
        // Pitfall 1 prevention: AbacContext is public but not referenced in
        // library code during Phase 22 (Phase 26 wires it in). Constructing
        // the default here both prevents the dead_code warning and locks the
        // D-10 invariant: no `agent` field, both application fields None.
        let ctx = AbacContext::default();
        assert!(ctx.source_application.is_none());
        assert!(ctx.destination_application.is_none());
    }

    #[test]
    fn test_abac_context_round_trip() {
        use crate::endpoint::{AppIdentity, AppTrustTier, SignatureState};
        let ctx = AbacContext {
            source_application: Some(AppIdentity {
                image_path: r"C:\app.exe".to_string(),
                publisher: "Contoso".to_string(),
                trust_tier: AppTrustTier::Trusted,
                signature_state: SignatureState::Valid,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            ..Default::default()
        };
        let json = serde_json::to_string(&ctx).unwrap();
        let rt: AbacContext = serde_json::from_str(&json).unwrap();
        assert_eq!(
            rt.source_application.as_ref().map(|a| a.publisher.as_str()),
            Some("Contoso"),
        );
        assert!(rt.destination_application.is_none());
        // Destination app is None, so the key must be absent from JSON.
        assert!(!json.contains("destination_application"));
    }

    #[test]
    fn test_evaluate_request_app_identity_fields_round_trip() {
        use crate::endpoint::{AppIdentity, AppTrustTier, SignatureState};
        let req = EvaluateRequest {
            source_application: Some(AppIdentity {
                image_path: r"C:\src.exe".to_string(),
                publisher: "Adobe Inc.".to_string(),
                trust_tier: AppTrustTier::Trusted,
                signature_state: SignatureState::Valid,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            destination_application: Some(AppIdentity {
                image_path: r"C:\dst.exe".to_string(),
                publisher: "Unknown".to_string(),
                trust_tier: AppTrustTier::Untrusted,
                signature_state: SignatureState::NotSigned,
                aumid: None,
                package_family_name: None,
                is_uwp: false,
            }),
            ..Default::default()
        };
        let json = serde_json::to_string(&req).unwrap();
        let rt: EvaluateRequest = serde_json::from_str(&json).unwrap();
        assert_eq!(
            rt.source_application
                .as_ref()
                .map(|a| a.image_path.as_str()),
            Some(r"C:\src.exe"),
        );
        assert_eq!(
            rt.destination_application
                .as_ref()
                .map(|a| a.image_path.as_str()),
            Some(r"C:\dst.exe"),
        );
    }

    #[test]
    fn test_app_field_aumid_serde() {
        let json = serde_json::to_string(&AppField::Aumid).unwrap();
        assert_eq!(json, "\"aumid\"");
