    let import_dir = data_directory.offset(8); // 1 * 8
    let import_rva = *(import_dir as *const u32) as isize;
    let _import_size = *((import_dir.offset(4)) as *const u32);

    if import_rva == 0 {
        return None;
    }

    let mut desc = module_base.offset(import_rva) as *const u8;
    loop {
        let name_rva = *((desc.offset(12)) as *const u32) as isize;
        if name_rva == 0 {
