    #[test]
    fn hash_path_is_deterministic() {
        let h1 = hash_path(r"C:\Users\test\file.txt");
        let h2 = hash_path(r"C:\Users\test\file.txt");
        assert_eq!(h1, h2);
        let h3 = hash_path(r"C:\Users\test\other.txt");
        assert_ne!(h1, h3);
    }

    #[test]
    fn pcwstr_roundtrip() {
        let wide: Vec<u16> = "Hello World".encode_utf16().chain(std::iter::once(0)).collect();
        let s = unsafe { pcwstr_to_string(PCWSTR::from_raw(wide.as_ptr())) };
        assert_eq!(s, "Hello World");
    }

    #[test]
    fn pcwstr_null_returns_empty() {
        let s = unsafe { pcwstr_to_string(PCWSTR::from_raw(std::ptr::null())) };
        assert_eq!(s, "");
    }

    #[test]
    fn pipe_client_connection_refused_when_no_server() {
        let req = HookRequest {
            path: r"C:\test.txt".to_string(),
            action: "CREATE".to_string(),
        };
        let result = pipe_client::send_request(
            r"\\.\pipe\DlpHookPipeTestNoServer",
            &req,
            100,
        );
        assert!(
            matches!(result, Err(pipe_client::PipeError::ConnectionRefused)),
            "expected ConnectionRefused, got {:?}",
            result
        );
    }

    #[test]
    fn pipe_client_roundtrip_deny() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestDeny";
        let _server = start_mock_pipe_server(pipe_name, Decision::DENY);

        let req = HookRequest {
            path: r"C:\secret.txt".to_string(),
            action: "CREATE".to_string(),
        };
        let resp = pipe_client::send_request(pipe_name, &req, 1000)
            .expect("send_request should succeed");
        assert_eq!(resp.decision, Decision::DENY);
        assert_eq!(resp.reason, "mock");
    }

    #[test]
    fn pipe_client_roundtrip_allow() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestAllow";
        let _server = start_mock_pipe_server(pipe_name, Decision::ALLOW);

        let req = HookRequest {
            path: r"C:\public.txt".to_string(),
            action: "CREATE".to_string(),
        };
        let resp = pipe_client::send_request(pipe_name, &req, 1000)
            .expect("send_request should succeed");
        assert_eq!(resp.decision, Decision::ALLOW);
    }

    #[test]
    fn hook_createfilew_fail_closed_on_deny() {
        // This test verifies the hook function's logic by calling it
        // directly with a mock pipe server that returns DENY.
        let pipe_name = r"\\.\pipe\DlpHookPipeTestHookDeny";
        let _server = start_mock_pipe_server(pipe_name, Decision::DENY);

        // Temporarily override the default pipe name for this test.
        // We can't easily do that without a global, so instead we'll
        // test classify_path directly.
        let result = classify_path(r"C:\secret.txt", "CREATE");
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Decision::DENY);
    }

    #[test]
    fn hook_createfilew_allow_when_allowed() {
        let pipe_name = r"\\.\pipe\DlpHookPipeTestHookAllow";
        let _server = start_mock_pipe_server(pipe_name, Decision::ALLOW);

        let result = classify_path(r"C:\public.txt", "CREATE");
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), Decision::ALLOW);
    }

    #[test]
    fn unhook_all_does_not_panic_when_not_initialised() {
        // UnhookAll should be safe to call even if init() never ran.
        UnhookAll();
    }

    #[test]
    fn find_iat_entry_returns_none_for_invalid_module() {
        unsafe {
            let result = find_iat_entry(
                std::ptr::null_mut(),
                "kernel32.dll",
                std::ptr::null(),
            );
            assert!(result.is_none());
        }
    }

    #[test]
    fn extract_nt_path_null() {
        unsafe {
            let s = extract_nt_path(std::ptr::null_mut());
            assert_eq!(s, "");
        }
    }
}

