            FILE_SHARE_NONE,
            None,
            OPEN_EXISTING,
            FILE_FLAGS_AND_ATTRIBUTES(0),
            None,
        )
    };

    match handle {
        Ok(h) if h != INVALID_HANDLE_VALUE => Ok(h),
        Ok(_) => Err(PipeError::ConnectionRefused),
        Err(e) => {
            let code = (e.code().0 as u32) & 0xFFFF;
            Err(PipeError::Win32(code))
        }
    }
}

